const D = { density: .6, scale: 1, energy: .6, hue: 132, speed: 1, warp: .3, x: .5, y: .46, seed: 0, style: 'canopy', act: 'deep' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:v>b?b:v;
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const sty = P.style, H = P.hue;
const hz = cl(P.y,.28,.72)*height, cx = cl(P.x,.05,.95)*width;
const groundH = Math.max(20, height - hz);
const yOf = t => hz + Math.pow(t,1.7)*groundH;
const hwOf = t => width*(.05 + t*.95)*.5*P.scale;
const NR = Math.round(9 + P.density*26);
const NC = Math.round(5 + P.density*12);

S.bass = (S.bass||0)*.82 + (A.bass||0)*.18;
S.tre  = (S.tre||0)*.82 + (A.treble||0)*.18;
const glow = (.4 + .6*P.energy) * (.5 + .6*K.intensity);
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + S.bass*.7);

// real-time scroll (never re-phases)
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
let sp = P.speed*(.45 + .8*K.intensity);
if (P.act === 'throb') sp *= 1 + .9*kick;
if (P.act === 'bloom') sp *= .35 + .8*(.5 + .5*Math.sin(K.t*.045 + K.section));
S.scroll = (S.scroll||0) + dt*sp*.42;
const scroll = S.scroll;

// ---- cached base: deep shadowed floor + static undergrowth / roots ----
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+P.seed+'|'+Math.round(P.density*6)+'|'+Math.round(P.y*24)+'|'+Math.round(P.scale*8);
if (!S.base || S.key !== key) {
  const g = (S.base && S.base.width===width && S.base.height===height) ? S.base : createGraphics(width,height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const STR = 56;
  // dense canopy shadow above horizon
  for (let i=0;i<STR;i++){ const f=i/STR, y=f*hz; let h,s,b;
    if (sty==='biolum'){ h=H; s=40; b=3+4*f; }
    else if (sty==='noir'){ h=150; s=16-8*f; b=3+9*f; }
    else if (sty==='thermal'){ h=232-70*f; s=64; b=4+12*f; }
    else if (sty==='emerald'){ h=H; s=72; b=6+14*f; }
    else { h=H; s=58-14*f; b=5+13*f; }
    g.fill(h,s,cl(b,2,84),100); g.rect(0,y-1,width,hz/STR+2);
  }
  // upper canopy light gap glow (so it's not pitch black up top)
  if (sty!=='noir'){ g.push(); g.blendMode(ADD);
    for (let i=0;i<6;i++){ const r=(6-i)*hz*.06; g.fill(sty==='thermal'?44:(H-30), 50, sty==='biolum'?70:80, 6);
      g.ellipse(cx+(fr(1)*2-1)*width*.2, hz*.2, width*.5, r); } g.pop(); }
  // ground plane (deep foreground -> lit far haze)
  for (let i=0;i<STR;i++){ const t=i/STR, y=yOf(t), y2=yOf((i+1)/STR); let h,s,b;
    if (sty==='biolum'){ h=H; s=44; b=4+16*Math.pow(t,1.3); }
    else if (sty==='noir'){ h=150; s=cl(12-8*t,0,14); b=5+30*Math.pow(t,1.3); }
    else if (sty==='thermal'){ h=250-250*Math.pow(t,1.25); s=84; b=10+66*Math.pow(t,1.5); if(t>.86){h=46;s=cl(30-160*(t-.86),0,40);b=92;} }
    else if (sty==='emerald'){ h=(H+8 - 12*t); s=70-14*t; b=8+30*Math.pow(t,1.2); }
    else { h=(H - 6 + 10*t); s=60-16*t; b=7 + 26*Math.pow(t,1.2); }
    g.fill(h,s,cl(b,3,88),100); g.rect(0,y-1,width,(y2-y)+2);
  }
  // static undergrowth
  g.push();
  if (sty==='biolum'){ // glowing spore network = non-representational
    g.blendMode(ADD);
    const nodes=[]; const NN=Math.round(30+P.density*40);
    for (let i=0;i<NN;i++){ const t=.1+fr(i*2)*.88, y=yOf(t), hw=hwOf(t); nodes.push([cx+(fr(i*2+1)*2-1)*hw, y, t]); }
    g.stroke(H,60,80,10); g.strokeWeight(1);
    for (let i=0;i<NN;i++){ const j=(i+1)%NN; if (fr(i*5)>.5) g.line(nodes[i][0],nodes[i][1],nodes[j][0],nodes[j][1]); }
    g.noStroke();
    for (let i=0;i<NN;i++){ const n=nodes[i]; g.fill((H+40*fr(i))%360,50,90,24); g.ellipse(n[0],n[1],2+n[2]*5,2+n[2]*5); }
  } else {
    // scattered ferns/leaves litter, seed-deterministic
    for (let i=0;i<240;i++){ const t=.06+fr(i*3)*.94, y=yOf(t), hw=hwOf(t), x=cx+(fr(i*3+1)*2-1)*hw;
      const h=(H - 20 + fr(i*3+2)*46), s=sty==='noir'?12:(sty==='thermal'?60:66), b=(sty==='noir'?16:14)+fr(i)*18 + t*12;
      g.fill(h,s,cl(b,4,74),90); g.push(); g.translate(x,y); g.rotate(fr(i*3)*6.28);
      const sz=(1.4+t*7); g.ellipse(0,0,sz*1.8,sz*.7); g.pop(); }
    // heavy foreground shadow
    g.blendMode(sty==='noir'?BLEND:MULTIPLY);
    for (let d=0;d<5;d++){ const t=(d+2)/8, y=yOf(t), hw=hwOf(t);
      g.fill(H, 40, 20, 16); g.ellipse(cx+(fr(d)*2-1)*hw*.5, y+groundH*.03, hw*1.5, groundH*.09); }
  }
  g.pop();
  S.base = g; S.key = key;
}
image(S.base,0,0);

// ---- god-ray light shafts from canopy, sweeping (real-time, big area) ----
if (sty!=='biolum'){ push(); blendMode(ADD); noStroke();
  const NB=4;
  for (let i=0;i<NB;i++){ const ph=K.t*(.06+.03*i) + i*1.9;
    const bx=cx + Math.sin(ph)*width*.34; const topw=width*.02, botw=width*.14*P.scale;
    const yb=yOf(.55); const rh = sty==='thermal'?44:(H-24);
    fill(rh, sty==='noir'?10:44, sty==='noir'?60:92, (3+5*glow)*(.6+.5*Math.sin(ph*.7)));
    beginShape(); vertex(bx-topw,0); vertex(bx+topw,0); vertex(bx+botw,yb); vertex(bx-botw,yb); endShape(CLOSE);
  }
  pop();
}

// ---- scrolling root/vine lines toward viewer (motion gate) ----
noFill();
for (let r=0;r<=NR;r++){ let t=(r - (scroll%1))/NR; if (t<=0.01||t>1) continue;
  const y=yOf(t), hw=hwOf(t), near=t;
  let h,s,b,a,sw;
  if (sty==='biolum'){ h=(H+30); s=60; b=95; a=10+40*near; sw=.6+near*2.0; }
  else if (sty==='thermal'){ h=250-250*Math.pow(t,1.25); s=88; b=100; a=10+44*near; sw=.5+near*2.0; }
  else if (sty==='noir'){ h=150; s=10; b=100; a=8+40*near; sw=.5+near*2.0; }
  else if (sty==='emerald'){ h=(H+14); s=80; b=96; a=12+42*near; sw=.6+near*2.4; }
  else { h=(H+8); s=48; b=80; a=8+40*near; sw=.5+near*2.6; }
  stroke(h,s,b, a*(.55+.6*glow));
  strokeWeight(sw);
  if (sty==='biolum'){ drawingContext.shadowBlur=(4+10*near)*glow; drawingContext.shadowColor=color(h,s,100,80).toString(); }
  beginShape();
  for (let u=0;u<=1.001;u+=1/10){ const xx=-hw+u*2*hw;
    const wob=Math.sin(u*6 + r*.8 + K.t*.6)*groundH*.012*near + Math.sin(u*2 - scroll*1.1)*groundH*.016*near;
    vertex(cx+xx, y+wob); }
  endShape();
}
drawingContext.shadowBlur=0;

// ---- converging vines (perspective verticals, harvest character) ----
const warp=P.warp;
const wx=(u,t)=>{ const d=(u-.5); return cx + d*width*(.03 + t*t*1.9)*P.scale*(1+warp*1.3*d*d*4*(1-t)); };
for (let c=0;c<=NC;c++){ const u=c/NC; let h,s,b,a,sw;
  if (sty==='biolum'){ h=(H+50); s=60; b=92; a=26; sw=1.0; }
  else if (sty==='thermal'){ h=20; s=80; b=95; a=22; sw=1.0; }
  else if (sty==='noir'){ h=150; s=8; b=90; a=18; sw=1.0; }
  else { h=(H-4); s=46; b=64; a=22; sw=1.1; }
  stroke(h,s,b, a*(.6+.5*glow)); strokeWeight(sw);
  line(wx(u,0)*.001+cx*.999, hz, wx(u,1), height);
}

// ---- rising spores / fireflies (continuous travel toward horizon) ----
const NP=Math.round(P.density*74);
push(); blendMode(sty==='noir'?SCREEN:ADD); noStroke();
for (let i=0;i<NP;i++){ const lane=fr(i*4), spd=.5+fr(i*4+1)*1.1;
  let prog=(fr(i*4+2) + (scroll*.12 + K.t*.05)*spd)%1; const t=1-prog; if (t<=.02) continue;
  const y=yOf(t), hw=hwOf(t);
  const x=cx+(lane*2-1)*hw*.95 + Math.sin(K.t*.7 + i)*hw*.04;
  const sz=(1.3+5.5*t)*(1+.5*S.tre);
  let h = sty==='thermal'?(18+40*t): sty==='noir'?150: sty==='biolum'?(H+30):(H+40*fr(i*4+3));
  let s = sty==='noir'?12:70;
  const a=(9+38*t)*(.5+.9*glow)*(.6+.7*fr(i*4+1));
  fill(h,s,100,Math.min(44,a)); ellipse(x,y,sz,sz);
}
pop();

// ---- horizon light-gap flare on the beat (partial-frame, strobe-safe) ----
push(); blendMode(ADD); noStroke();
const flare=(kick*.5 + K.swell*.4)*glow;
const fh = sty==='thermal'?46: sty==='noir'?150:(H-20);
for (let i=0;i<5;i++){ const rr=(5-i)*groundH*.05*(1+flare);
  fill(fh, sty==='noir'?10:50, sty==='noir'?66:94, 3+7*flare);
  rect(0, hz-rr*.42, width, rr); }
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
